[poolsize, dataFormat, NumDims.sequential_1_efficientnetb0_1_block7a_35] = prepareGlobalAveragePoolArgs(Vars.sequential_1_efficientnetb0_1_block7a__3, NumDims.sequential_1_efficientnetb0_1_block7a__3);
Vars.sequential_1_efficientnetb0_1_block7a_35 = avgpool(Vars.sequential_1_efficientnetb0_1_block7a__3, poolsize, 'DataFormat', dataFormat);

% Squeeze:
[Vars.sequential_1_efficientnetb0_1_block7a_37, NumDims.sequential_1_efficientnetb0_1_block7a_37] = onnxSqueeze(Vars.sequential_1_efficientnetb0_1_block7a_35, Vars.const_axes__1282, NumDims.sequential_1_efficientnetb0_1_block7a_35);

% Reshape:
[shape, NumDims.sequential_1_efficientnetb0_1_block7a_27] = prepareReshapeArgs(Vars.sequential_1_efficientnetb0_1_block7a_37, Vars.new_shape__1127, NumDims.sequential_1_efficientnetb0_1_block7a_37, 0);
Vars.sequential_1_efficientnetb0_1_block7a_27 = reshape(Vars.sequential_1_efficientnetb0_1_block7a_37, shape{:});

% Conv:
[weights, bias, stride, dilationFactor, padding, dataFormat, NumDims.sequential_1_efficientnetb0_1_block7a_25] = prepareConvArgs(Vars.sequential_1_efficientnetb0_1_block7a_31, Vars.sequential_1_efficientnetb0_1_block7a_30, Vars.ConvStride1233, Vars.ConvDilationFactor1234,Vars.ConvPadding1235, 1, NumDims.sequential_1_efficientnetb0_1_block7a_27, NumDims.sequential_1_efficientnetb0_1_block7a_31);
Vars.sequential_1_efficientnetb0_1_block7a_25 = dlconv(Vars.sequential_1_efficientnetb0_1_block7a_27, weights, bias, 'Stride', stride, 'DilationFactor', dilationFactor, 'Padding', padding, 'DataFormat', dataFormat);

% Sigmoid:
Vars.sequential_1_efficientnetb0_1_block7a_29 = sigmoid(dlarray(Vars.sequential_1_efficientnetb0_1_block7a_25));
NumDims.sequential_1_efficientnetb0_1_block7a_29 = NumDims.sequential_1_efficientnetb0_1_block7a_25;

% Mul:
Vars.sequential_1_efficientnetb0_1_block7a_33 = Vars.sequential_1_efficientnetb0_1_block7a_25 .* Vars.sequential_1_efficientnetb0_1_block7a_29;
NumDims.sequential_1_efficientnetb0_1_block7a_33 = max(NumDims.sequential_1_efficientnetb0_1_block7a_25, NumDims.sequential_1_efficientnetb0_1_block7a_29);

% Reshape:
[shape, NumDims.sequential_1_efficientnetb0_1_block7a_19] = prepareReshapeArgs(Vars.sequential_1_efficientnetb0_1_block7a_33, Vars.new_shape__1129, NumDims.sequential_1_efficientnetb0_1_block7a_33, 0);
Vars.sequential_1_efficientnetb0_1_block7a_19 = reshape(Vars.sequential_1_efficientnetb0_1_block7a_33, shape{:});

% Conv:
[weights, bias, stride, dilationFactor, padding, dataFormat, NumDims.sequential_1_efficientnetb0_1_block7a_17] = prepareConvArgs(Vars.sequential_1_efficientnetb0_1_block7a_23, Vars.sequential_1_efficientnetb0_1_block7a_22, Vars.ConvStride1236, Vars.ConvDilationFactor1237,Vars.ConvPadding1238, 1, NumDims.sequential_1_efficientnetb0_1_block7a_19, NumDims.sequential_1_efficientnetb0_1_block7a_23);
Vars.sequential_1_efficientnetb0_1_block7a_17 = dlconv(Vars.sequential_1_efficientnetb0_1_block7a_19, weights, bias, 'Stride', stride, 'DilationFactor', dilationFactor, 'Padding', padding, 'DataFormat', dataFormat);

% Sigmoid:
Vars.sequential_1_efficientnetb0_1_block7a_21 = sigmoid(dlarray(Vars.sequential_1_efficientnetb0_1_block7a_17));
NumDims.sequential_1_efficientnetb0_1_block7a_21 = NumDims.sequential_1_efficientnetb0_1_block7a_17;

% Mul:
Vars.sequential_1_efficientnetb0_1_block7a_15 = Vars.sequential_1_efficientnetb0_1_block7a__3 .* Vars.sequential_1_efficientnetb0_1_block7a_21;
NumDims.sequential_1_efficientnetb0_1_block7a_15 = max(NumDims.sequential_1_efficientnetb0_1_block7a__3, NumDims.sequential_1_efficientnetb0_1_block7a_21);

% Conv:
[weights, bias, stride, dilationFactor, padding, dataFormat, NumDims.Conv__1026_0] = prepareConvArgs(Vars.sequential_1_efficientnetb0_1_block7a_14, Vars.sequential_1_efficientnetb0_1_block7a_pr, Vars.ConvStride1239, Vars.ConvDilationFactor1240,Vars.ConvPadding1241, 1, NumDims.sequential_1_efficientnetb0_1_block7a_15, NumDims.sequential_1_efficientnetb0_1_block7a_14);
Vars.Conv__1026_0 = dlconv(Vars.sequential_1_efficientnetb0_1_block7a_15, weights, bias, 'Stride', stride, 'DilationFactor', dilationFactor, 'Padding', padding, 'DataFormat', dataFormat);

% Conv:
[weights, bias, stride, dilationFactor, padding, dataFormat, NumDims.Conv__1028_0] = prepareConvArgs(Vars.sequential_1_efficientnetb0_1_top_conv_1, Vars.sequential_1_efficientnetb0_1_top_bn_1_b, Vars.ConvStride1242, Vars.ConvDilationFactor1243,Vars.ConvPadding1244, 1, NumDims.Conv__1026_0, NumDims.sequential_1_efficientnetb0_1_top_conv_1);
Vars.Conv__1028_0 = dlconv(Vars.Conv__1026_0, weights, bias, 'Stride', stride, 'DilationFactor', dilationFactor, 'Padding', padding, 'DataFormat', dataFormat);

% Sigmoid:
