% GlobalAveragePool:
[poolsize, dataFormat, NumDims.sequential_1_global_average_pooling2d__1] = prepareGlobalAveragePoolArgs(Vars.sequential_1_efficientnetb0_1_top_acti_3, NumDims.sequential_1_efficientnetb0_1_top_acti_3);
