% Squeeze:
[Vars.sequential_1_global_average_pooling2d__3, NumDims.sequential_1_global_average_pooling2d__3] = onnxSqueeze(Vars.sequential_1_global_average_pooling2d__1, Vars.const_axes__1282, NumDims.sequential_1_global_average_pooling2d__1);

