end

function [inputDataPerms, outputDataPerms, Training] = parseInputs(input, sequential_1_efficientnetb0_1_normaliz_2, sequential_1_efficientnetb0_1_normalizat, numDataOutputs, params, varargin)
% Function to validate inputs to drClassifierFcn:
p = inputParser;
isValidArrayInput = @(x)isnumeric(x) || isstring(x);
isValidONNXParameters = @(x)isa(x, 'ONNXParameters');
addRequired(p, 'input', isValidArrayInput);
addRequired(p, 'sequential_1_efficientnetb0_1_normaliz_2', isValidArrayInput);
addRequired(p, 'sequential_1_efficientnetb0_1_normalizat', isValidArrayInput);
addRequired(p, 'params', isValidONNXParameters);
addParameter(p, 'InputDataPermutation', 'auto');
addParameter(p, 'OutputDataPermutation', 'auto');
addParameter(p, 'Training', false);
parse(p, input, sequential_1_efficientnetb0_1_normaliz_2, sequential_1_efficientnetb0_1_normalizat, params, varargin{:});
inputDataPerms = p.Results.InputDataPermutation;
outputDataPerms = p.Results.OutputDataPermutation;
Training = p.Results.Training;
if isnumeric(inputDataPerms)
    inputDataPerms = {inputDataPerms};
end
if isstring(inputDataPerms) && isscalar(inputDataPerms) || ischar(inputDataPerms)
    inputDataPerms = repmat({inputDataPerms},1,3);
end
if isnumeric(outputDataPerms)
    outputDataPerms = {outputDataPerms};
end
if isstring(outputDataPerms) && isscalar(outputDataPerms) || ischar(outputDataPerms)
    outputDataPerms = repmat({outputDataPerms},1,numDataOutputs);
end
end

function [input, sequential_1_efficientnetb0_1_normaliz_2, sequential_1_efficientnetb0_1_normalizat, Training, outputDataPerms, anyDlarrayInputs] = preprocessInput(input, sequential_1_efficientnetb0_1_normaliz_2, sequential_1_efficientnetb0_1_normalizat, params, varargin)
% Parse input arguments
[inputDataPerms, outputDataPerms, Training] = parseInputs(input, sequential_1_efficientnetb0_1_normaliz_2, sequential_1_efficientnetb0_1_normalizat, 1, params, varargin{:});
anyDlarrayInputs = any(cellfun(@(x)isa(x, 'dlarray'), {input, sequential_1_efficientnetb0_1_normaliz_2, sequential_1_efficientnetb0_1_normalizat}));
% Make the input variables into unlabelled dlarrays:
input = makeUnlabeledDlarray(input);
