sequential_1_efficientnetb0_1_normalizat = makeUnlabeledDlarray(sequential_1_efficientnetb0_1_normalizat);
% Permute inputs if requested:
input = permuteInputVar(input, inputDataPerms{1}, 4);
sequential_1_efficientnetb0_1_normaliz_2 = permuteInputVar(sequential_1_efficientnetb0_1_normaliz_2, inputDataPerms{2}, 4);
